"""Emit a typed client from exactly the document served at /v1/openapi.json."""

import json
from pathlib import Path
from tempfile import TemporaryDirectory

from app.main import app

OUTPUT = Path(__file__).resolve().parents[3] / "packages/api-client/src/index.ts"


def main() -> None:
    document = json.dumps(app.openapi(), ensure_ascii=False, sort_keys=True, indent=2)
    source = (
        "// Generated by pnpm gen:api. Edit the FastAPI route or models to change it.\n"
        'import type { NormalizeOAS } from "fets";\n\n'
        "// Metro's ESM transform shadows the global Object in TypeBox.\n"
        'const { createClient }: typeof import("fets") = require("fets");\n\n'
        f"export type ApiDocument = {document};\n\n"
        "export function createApiClient(endpoint: string) {\n"
        "  return createClient<NormalizeOAS<ApiDocument>>({ endpoint, fetchFn: fetch });\n"
        "}\n"
    )
    with TemporaryDirectory(dir=OUTPUT.parent) as directory:
        temporary = Path(directory) / OUTPUT.name
        temporary.write_text(source, encoding="utf-8", newline="\n")
        temporary.replace(OUTPUT)


if __name__ == "__main__":
    main()
